mapper.select:
SELECT id, title, system_logo_url, background_image_url, tenant_id, config_type, creator, create_time, modifier, update_time, delete_flag FROM vm_personal_login_conf_t WHERE delete_flag = '0' AND config_type = #{configType}
AND tenant_id = #{tenantId}
ORDER BY create_time DESC

mapper.update:
